                include_total?: string;
                /** @description Comma-separated facet names. Unknown token is 400 UNKNOWN_FACET. */
                facets?: string;
                /** @description Closed per-collection sort key. */
                sort?: string;
                /** @description true includes r18. false or absent hides r18. Only true or false. */
                nsfw?: string;
                /** @description Work title search. Switches this collection to the search index; sort defaults to relevance. Must not be used as a discriminant. */
                q?: string;
                /** @description Closed: all_ages, sensitive, r18. r18 requires nsfw=true. */
                content_rating?: string;
                /** @description true or false. Absent = no gate. */
                claimed?: string;
                /** @description Comma-separated closed states: none, live, draft. pending, declined and hidden are the per-site moderation queue: they need a key holding claim_events:read and a site= naming the caller's own site, and are otherwise not in the vocabulary. */
                claim_state?: string;
                /** @description Comma-separated closed editorial axis: sfw, nsfw. */
                content_limit?: string;
                /** @description Claiming site key. Open vocabulary; unknown values match nothing. */
                site?: string;
                /** @description The claiming site's own user id of the claim owner. Requires site=. Live registry filter; cannot be combined with q=, page= or search sorts. */
                owner_uid?: string;
                /** @description Catalog company id. Live registry filter when q= is absent. */
                company_id?: string;
                /** @description true expands company_id one hop down imprint/subsidiary. Only true or false. */
                company_rollup?: string;
                /** @description Comma-separated canonical tag ids, AND, max 10. */
                tag_id?: string;
                /** @description Comma-separated canonical tag ids, max 100. Drops every work that carries any of them, from any source and at any spoiler level. ANDed with the other filters, tag_id included: a tag named in both leaves nothing. */
                exclude_tag_id?: string;
                /** @description Comma-separated canonical tag ids, max 100. As exclude_tag_id, and each id also drops the works carrying any tag below it in the tag hierarchy (Tag.descendant_count counts them). */
                exclude_tag_tree?: string;
                /** @description Catalog series id. */
                series_id?: string;
                /** @description Catalog engine id. */
                engine_id?: string;
                /** @description Open vocabulary platform token. Unknown matches nothing. */
                platform?: string;
                /** @description YYYY-MM-DD inclusive, on each work's release_date. */
                released_after?: string;
